import { aliveTagger } from "@alive-game/alive-tagger"
import tailwindcss from "@tailwindcss/vite"
import react from "@vitejs/plugin-react-swc"
import { defineConfig } from "vite"

const PORT = Number(process.env.PORT) || 3594
const API_PORT = PORT + 1000

export default defineConfig(({ mode }) => ({
  server: {
    host: "::",
    port: PORT,
    allowedHosts: [".example.com"],
    hmr: {
      protocol: "wss",
      clientPort: 443,
    },
    // .env.development is regenerated by the platform every few minutes. Vite
    // treats an env-file change as a config change and does a full server
    // restart; each restart leaked memory until the dev server died with an
    // out-of-memory abort. Nothing here reads import.meta.env, so ignore them.
    watch: {
      ignored: ["**/.env", "**/.env.*"],
    },
    proxy: {
      "/api": {
        target: `http://localhost:${API_PORT}`,
        changeOrigin: true,
      },
      // The gate turns itself on the moment CRM_PASSWORD is set, and the platform
      // writes that secret into .env.development — so dev is gated too, not only
      // production. `fetchApi` answers a 401 by sending the tab to /login, which
      // exists only on the API server; unproxied, Vite's SPA fallback served
      // index.html instead and the router rendered NotFound. Signing in looked
      // exactly like a broken route.
      "/login": {
        target: `http://localhost:${API_PORT}`,
        changeOrigin: true,
      },
      "/logout": {
        target: `http://localhost:${API_PORT}`,
        changeOrigin: true,
      },
    },
  },
  preview: {
    host: "::",
    port: PORT,
    allowedHosts: [".example.com"],
  },
  // No `resolve.alias` for `@/`: source imports resolve through the `#/*`
  // subpath declared in package.json `imports`, which Vite and TypeScript
  // both read on their own. One place to change, not three.
  plugins: [react(), tailwindcss(), mode === "development" && aliveTagger()].filter(Boolean),
}))
